import SwiftUI

/// The glyph language (UI-CONCEPT §7.2): one custom symbol per state, distinguishable as 16 px template images.
/// Connecting and reasserting share the "transition" family but differ in their badge (§6.1).
enum GlyphState: String, Sendable, CaseIterable {
    case unprotected
    case connecting
    case reasserting
    case protected
    case blocked
    case attention
    case paused
    case errorStopped

    /// Asset name in `Assets.xcassets/Symbols` (generated by `native/Tools/ui/gen_lock_symbols.py`).
    var symbolName: String {
        switch self {
        case .unprotected: "lockplus.lock.open"
        case .connecting: "lockplus.lock.connecting"
        case .reasserting: "lockplus.lock.reasserting"
        case .protected: "lockplus.lock.closed"
        case .blocked: "lockplus.lock.blocked"
        case .attention: "lockplus.lock.attention"
        case .paused: "lockplus.lock.paused"
        case .errorStopped: "lockplus.lock.error"
        }
    }

    /// Glyph color when color is allowed (§7.2). Glyph roles need ≥ 3:1, so the light glyph variants are fine here.
    var color: Color {
        switch self {
        case .unprotected: Color.lp.unprotected
        case .connecting, .reasserting: Color.lp.transition
        case .protected: Color.lp.protected
        case .blocked, .attention, .paused: Color.lp.attention
        case .errorStopped: Color.lp.critical
        }
    }

    /// Text color for the state word next to the glyph (text needs 4.5:1: the darker light-mode variants).
    var textColor: Color {
        switch self {
        case .unprotected: Color.primary
        case .connecting, .reasserting: Color.lp.transitionText
        case .protected: Color.primary
        case .blocked, .attention, .paused: Color.lp.attentionText
        case .errorStopped: Color.lp.criticalText
        }
    }

    /// Status-item connecting animation (§6.1): open → closing → closed outline, ~120 ms per frame.
    static let connectingFrames = ["lockplus.lock.open", "lockplus.lock.closing", "lockplus.lock.closed.outline"]
}

/// Card tint for the hero and the menu header (§7.3): sage when protected, orange when blocked, none when off.
enum StateTint: Sendable, Equatable {
    case none, protected, transition, attention, critical

    var color: Color? {
        switch self {
        case .none: nil
        case .protected: Color.lp.protected
        case .transition: Color.lp.transition
        case .attention: Color.lp.attention
        case .critical: Color.lp.critical
        }
    }
}
